    public void loadPlugins() {
        int id = this.ctx.getActivity().getResources().getIdentifier("config", "xml", this.ctx.getActivity().getPackageName());
        if (id == 0) {
            id = this.ctx.getActivity().getResources().getIdentifier("plugins", "xml", this.ctx.getActivity().getPackageName());
            LOG.i(TAG, "Using plugins.xml instead of config.xml.  plugins.xml will eventually be deprecated");
        }
        if (id == 0) {
            pluginConfigurationMissing();
            return;
        }
        XmlResourceParser xml = this.ctx.getActivity().getResources().getXml(id);
        int eventType = -1;
        String service = "";
        String pluginClass = "";
        boolean insideFeature = false;
        while (eventType != 1) {
            if (eventType == 2) {
                String strNode = xml.getName();
                if (strNode.equals("plugin")) {
                    service = xml.getAttributeValue(null, "name");
                    pluginClass = xml.getAttributeValue(null, "value");
                    boolean onload = "true".equals(xml.getAttributeValue(null, "onload"));
                    PluginEntry entry = new PluginEntry(service, pluginClass, onload);
                    addService(entry);
                } else if (strNode.equals("url-filter")) {
                    this.urlMap.put(xml.getAttributeValue(null, "value"), service);
                } else if (strNode.equals("feature")) {
                    insideFeature = true;
                    xml.getAttributeValue(null, "name");
                } else if (strNode.equals("param") && insideFeature) {
                    String paramType = xml.getAttributeValue(null, "name");
                    if (paramType.equals("service")) {
                        service = xml.getAttributeValue(null, "value");
                    } else if (paramType.equals("package")) {
                        pluginClass = xml.getAttributeValue(null, "value");
                    }
                    if (service.length() > 0 && pluginClass.length() > 0) {
                        boolean onload2 = "true".equals(xml.getAttributeValue(null, "onload"));
                        PluginEntry entry2 = new PluginEntry(service, pluginClass, onload2);
                        addService(entry2);
                        service = "";
                        pluginClass = "";
                    }
                }
            } else if (eventType == 3 && xml.getName().equals("feature")) {
                service = "";
                pluginClass = "";
