                this.results.put(createMediaFile(data2));
                if (this.results.length() >= this.limit) {
                    this.callbackContext.sendPluginResult(new PluginResult(PluginResult.Status.OK, this.results));
                    return;
                } else {
                    captureVideo(this.duration);
